+/**
+ * Upper bound of an element's stringified length, measured without
+ * stringifying it (nested arrays are walked) and stopping early once past
+ * the cap.
+ */
+function contentSize(value: unknown): number {
+	if (value === null || value === undefined) return 0;
+	if (typeof value === 'string') return value.length;
+	if (!isArray(value)) return toStr(value).length;
+
+	let size = value.length;
+	for (const element of value) {
+		size += contentSize(element);
+		if (size > MAX_RESULT_LENGTH) break;
+	}
+	return size;
+}
